import { continueRender, delayRender } from 'remotion';

export const alice = 'Alice';
export const sans = 'Inter Tight';
export const mono = 'JetBrains Mono';

export const c = {
  void: '#07030D',
  plumDeep: '#1A0A2E',
  plum: '#2D1153',
  core: '#7A2FB8',
  bright: '#9D4EDD',
  lilac: '#C77DFF',
  glow: '#E0AAFF',
  text: '#F6F1FB',
  textDim: 'rgba(246,241,251,0.55)',
} as const;

function b64dec(s: string): ArrayBuffer {
  const bin = atob(s);
  const buf = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) buf[i] = bin.charCodeAt(i);
  return buf.buffer;
}

const FONTS = {
  alice_latin:      '',
  alice_latin_ext:  '',
  it_latin:         '',
  it_latin_ext:     '',
  it_italic:        '',
  jbm_latin:        '',
  jbm_latin_ext:    '',
};

// Add font faces synchronously so they are in document.fonts before
// any frame is rendered. font-display:block tells the browser to wait
// for each font before painting text, so no async delay is needed here.
[
  ['Alice',          'alice_latin',     '400',     'normal'] as const,
  ['Alice',          'alice_latin_ext', '400',     'normal'] as const,
  ['Inter Tight',    'it_latin',        '100 900', 'normal'] as const,
  ['Inter Tight',    'it_latin_ext',    '100 900', 'normal'] as const,
  ['Inter Tight',    'it_italic',       '300',     'italic'] as const,
  ['JetBrains Mono', 'jbm_latin',       '100 800', 'normal'] as const,
  ['JetBrains Mono', 'jbm_latin_ext',   '100 800', 'normal'] as const,
].forEach(([family, key, weight, style]) => {
  const face = new FontFace(family, b64dec(FONTS[key]), {
    weight,
    style,
    display: 'block',
  });
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  (document.fonts as any).add(face);
});

// Synchronous: fonts are registered; rendering can start immediately.
const h = delayRender('fonts');
continueRender(h);
